use crate::stage13::{SecureBootOtp,SECURE_BOOT_OTP_OFFSET,REF_OTP_IO_ERROR,REF_SECURE_BOOT_ALREADY_ENABLED};
/// Binary-exact return-code surface of `sub_8411AE4`: 0 when programmed now,
/// 0xF0100003 when already non-zero, 0xFFFF0006 on OTP I/O failure.
pub fn ensure_secure_boot_reference_code<I:SecureBootOtp>(io:&mut I)->u32{let v=match io.read_secure_byte(SECURE_BOOT_OTP_OFFSET){Ok(v)=>v,Err(_)=>return REF_OTP_IO_ERROR};if v!=0{return REF_SECURE_BOOT_ALREADY_ENABLED}match io.write_secure_byte(SECURE_BOOT_OTP_OFFSET,0xFF){Ok(())=>0,Err(_)=>REF_OTP_IO_ERROR}}
#[cfg(test)]mod tests{use super::*;struct O{v:u8,fail_r:bool,fail_w:bool}impl SecureBootOtp for O{type Error=();fn read_secure_byte(&mut self,_:u16)->Result<u8,()>{if self.fail_r{Err(())}else{Ok(self.v)}}fn write_secure_byte(&mut self,_:u16,v:u8)->Result<(),()>{if self.fail_w{Err(())}else{self.v=v;Ok(())}}}#[test]fn reference_codes(){let mut fresh=O{v:0,fail_r:false,fail_w:false};assert_eq!(ensure_secure_boot_reference_code(&mut fresh),0);assert_eq!(fresh.v,0xff);let mut old=O{v:1,fail_r:false,fail_w:false};assert_eq!(ensure_secure_boot_reference_code(&mut old),0xF010_0003);let mut bad=O{v:0,fail_r:true,fail_w:false};assert_eq!(ensure_secure_boot_reference_code(&mut bad),0xFFFF_0006);}}
